input.command:
cat > candidate.mjs <<'EOF'
let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const { documentId, title, timestamp, idempotencyKey } = input;
const headers = { "content-type": "application/json" };
const outbound = [];
const ordering = [];

function observe(status, body, { rows = [], committed = false, messages = [], failures = [], retryability = false, extraHeaders = {} } = {}) {
  console.log(JSON.stringify({
    http: { status, headers: { ...headers, ...extraHeaders }, body },
    database: { rows, transaction: { committed } },
    messages, outbound, ordering, failures, retryability
  }));
}

function fail(status, code, retryability, extra = {}) {
  observe(status, { error: code }, { failures: [{ code, ...extra }], retryability, extraHeaders: extra.headers });
}

// Validation
if (typeof title !== "string" || title.trim() === "" || !documentId || !timestamp) {
  fail(400, "validation_failed", false);
} else if (input.existing && idempotencyKey && input.existing.idempotencyKey === idempotencyKey) {
  // Idempotent replay: no new side effects.
  const prior = input.existing;
  if (prior.title !== title) {
    fail(409, "idempotency_key_conflict", false);
  } else {
    const doc = { id: prior.documentId ?? documentId, title: prior.title, createdAt: prior.timestamp ?? timestamp };
    observe(200, doc, { rows: [], committed: false, extraHeaders: { "idempotent-replay": "true" } });
  }
} else {
  const call = (name, status) => {
    outbound.push({ vendor: name === "authorize" ? "authorization" : "search-index", operation: name, documentId, timestamp, idempotencyKey, status });
    ordering.push(`vendor.${name}`);
  };
  const classify = (status) => {
    if (status >= 200 && status < 300) return null;
    if (status === 401 || status === 403) return [403, "vendor_unauthorized", false];
    if (status === 429) return [503, "vendor_rate_limited", true];
    if (status >= 500) return [502, "vendor_unavailable", true];
    return [502, "vendor_rejected", false];
  };
  const authStatus = input.vendorStatus ?? 200;
  call("authorize", authStatus);
  let err = classify(authStatus);
  if (!err) {
    const idxStatus = input.indexStatus ?? 200;
    call("index", idxStatus);
    err = classify(idxStatus);
  }
  if (err) {
    const [status, code, retry] = err;
    fail(status, code, retry, { stage: outbound[outbound.length - 1].operation, vendorStatus: outbound[outbound.length - 1].status });
  } else {
    const row = { id: documentId, title, createdAt: timestamp, idempotencyKey: idempotencyKey ?? null };
    ordering.push("database.commit", "message.document.created");
    const messages = [{ type: "document.created", documentId, timestamp, idempotencyKey: idempotencyKey ?? null, payload: { id: documentId, title } }];
    observe(201, { id: documentId, title, createdAt: timestamp }, { rows: [row], committed: true, messages });
  }
}
EOF
npm test 2>&1 | tail -8

