let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const { documentId, title, timestamp, idempotencyKey } = input;
const outbound = [];
const ordering = [];

function observe(status, body, opts = {}) {
  const { rows = [], committed = false, messages = [], failures = [], retryability = false, extraHeaders = {} } = opts;
  console.log(JSON.stringify({
    http: { status, headers: { "content-type": "application/json", ...extraHeaders }, body },
    database: { rows, transaction: { committed } },
    messages, outbound, ordering, failures, retryability
  }));
}

function fail(status, code, retryability, extra = {}) {
  observe(status, { error: code }, { failures: [{ code, ...extra }], retryability });
}

function classify(status) {
  if (status >= 200 && status < 300) return null;
  if (status === 401 || status === 403) return [403, "vendor_unauthorized", false];
  if (status === 429) return [503, "vendor_rate_limited", true];
  if (status >= 500) return [502, "vendor_unavailable", true];
  return [502, "vendor_rejected", false];
}

function call(operation, status) {
  outbound.push({ vendor: operation === "authorize" ? "authorization" : "search-index", operation, documentId, timestamp, idempotencyKey, status });
  ordering.push(`vendor.${operation}`);
}

if (typeof title !== "string" || title.trim() === "" || !documentId || !timestamp) {
  fail(400, "validation_failed", false);
} else if (input.existing && idempotencyKey && input.existing.idempotencyKey === idempotencyKey) {
  // Idempotent replay: return the original result with no new side effects.
  const prior = input.existing;
  if (prior.title !== title) {
    fail(409, "idempotency_key_conflict", false);
  } else {
    observe(200, { id: prior.documentId ?? documentId, title: prior.title, createdAt: prior.timestamp ?? timestamp },
      { extraHeaders: { "idempotent-replay": "true" } });
  }
} else {
  const authStatus = input.vendorStatus ?? 200;
  call("authorize", authStatus);
  let err = classify(authStatus);
  if (!err) {
    const idxStatus = input.indexStatus ?? 200;
    call("index", idxStatus);
    err = classify(idxStatus);
  }
  if (err) {
    const last = outbound[outbound.length - 1];
    fail(err[0], err[1], err[2], { stage: last.operation, vendorStatus: last.status });
  } else {
    ordering.push("database.commit", "message.document.created");
    observe(201, { id: documentId, title, createdAt: timestamp }, {
      rows: [{ id: documentId, title, createdAt: timestamp, idempotencyKey: idempotencyKey ?? null }],
      committed: true,
      messages: [{ type: "document.created", documentId, timestamp, idempotencyKey: idempotencyKey ?? null, payload: { id: documentId, title } }]
    });
  }
}

